"hud_and_panels.all_systems_green_enjoy_it_while":"Todos los sistemas en verde. Disfrútalo mientras dure.",
"hud_and_panels.auto_fix_in_n_day":{"one":"Autorreparación en {n} día","other":"Autorreparación en {n} días"},
"hud_and_panels.blackholing_g":"blackhole de {g}",
